import { existsSync } from 'node:fs';
import { CommandError, runCommand } from '../adapters/command.js';
import { dirname, isAbsolute, resolve } from 'node:path';
import type { TallyConfig } from '../schema/index.js';
import { ConfigError } from './config.js';
import { checkDirectHarness, requireClaudeConsent } from '../adapters/direct.js';
import { aoClaudeSetupCommand } from './ao-claude-settings.js';

export type PreflightRunner = (file: string, args: string[]) => Promise<{ stdout: string; stderr: string }>;

function configRelative(configPath: string, path: string): string {
  return isAbsolute(path) ? path : resolve(dirname(configPath), path);
}

export function repoPath(config: TallyConfig, configPath: string): string {
  return configRelative(configPath, config.repo.path);
}

export function backlogPath(config: TallyConfig, configPath: string): string | null {
  if (config.backlog.source !== 'file' || config.backlog.file === undefined) return null;
  return configRelative(configPath, config.backlog.file);
}

function defaultRunner(file: string, args: string[]) {
  return runCommand(file, args);
}

interface AoProjectResponse {
  project?: {
    config?: unknown;
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function quoteShell(value: string): string {
  return `'${value.replaceAll("'", "'\\''")}'`;
}

export function withWorkerAutoMode(config: unknown): Record<string, unknown> {
  return withWorkerPermissionMode(config, 'auto');
}

export function aoWorkerMode(config: Pick<TallyConfig, 'tiers'>): 'default' | 'auto' {
  return config.tiers.some(tier => tier.harness === 'claude-code') ? 'default' : 'auto';
}

export function withWorkerPermissionMode(config: unknown, mode: 'default' | 'auto'): Record<string, unknown> {
  const base = isRecord(config) ? { ...config } : {};
  const worker = isRecord(base.worker) ? { ...base.worker } : {};
  const agentConfig = isRecord(worker.agentConfig) ? { ...worker.agentConfig } : {};
  agentConfig.permissions = mode;
  worker.agentConfig = agentConfig;
  base.worker = worker;
  return base;
}

function quoteJsonForShell(value: unknown): string {
  return quoteShell(JSON.stringify(value));
}

export function workerAutoModeFixCommand(projectId: string, projectConfig: unknown): string {
  const fixed = withWorkerAutoMode(projectConfig);
  return `ao project set-config ${projectId} --config-json ${quoteJsonForShell(fixed)}`;
}

export function workerPermissionMode(projectConfig: unknown): string | null {
  if (!isRecord(projectConfig)) return null;
  const worker = isRecord(projectConfig.worker) ? projectConfig.worker : {};
  const workerAgentConfig = isRecord(worker.agentConfig) ? worker.agentConfig : {};
  const workerPermission = workerAgentConfig.permissions;
  if (typeof workerPermission === 'string') return workerPermission;
  return null;
}

export interface WorkerPermissionCheck {
  ok: boolean;
  mode: string | null;
  detail: string;
  fix: string;
}

export function checkWorkerAutoMode(projectId: string, projectConfig: unknown): WorkerPermissionCheck {
  const mode = workerPermissionMode(projectConfig);
  const fix = workerAutoModeFixCommand(projectId, projectConfig);
  if (mode === 'auto') {
    return { ok: true, mode, detail: 'worker permission mode is auto', fix };
  }
  const label = mode ?? 'unset';
  return {
    ok: false,
    mode,
    detail: `worker permission mode is ${label}; unattended Tally workers can stall before setup, edits, tests, or commits`,
    fix,
  };
}

export function checkConfiguredWorkerMode(config: TallyConfig, projectConfig: unknown): WorkerPermissionCheck {
  const expected = aoWorkerMode(config);
  if (new Set(config.tiers.map(tier => tier.harness)).size > 1) {
    const mode = workerPermissionMode(projectConfig);
    return { ok: mode === 'auto' || mode === 'default', mode,
      detail: mode === 'auto' || mode === 'default' ? 'mixed AO workers select Codex auto or Claude default immediately before each spawn under a project lock'
        : `worker permission mode is ${mode ?? 'unset'}; mixed AO workers require a consented default or auto mode, never bypass-permissions`,
      fix: `ao project set-config ${config.repo.aoProject} --config-json ${quoteJsonForShell(withWorkerPermissionMode(projectConfig, expected))}` };
  }
  if (expected === 'auto') return checkWorkerAutoMode(config.repo.aoProject!, projectConfig);
  const mode = workerPermissionMode(projectConfig);
  return { ok: mode === expected, mode,
    detail: mode === expected ? 'worker permission mode is default; Claude uses its consented worktree-local dontAsk rules'
      : `worker permission mode is ${mode ?? 'unset'}; Claude AO workers require default so their local dontAsk allow-list is not overridden`,
    fix: `ao project set-config ${config.repo.aoProject} --config-json ${quoteJsonForShell(withWorkerPermissionMode(projectConfig, expected))}` };
}

export function checkClaudePostCreate(config: TallyConfig, configPath: string, projectConfig: unknown): SetupPostCreateCheck | null {
  if (!config.tiers.some(tier => tier.harness === 'claude-code')) return null;
  const hook = aoClaudeSetupCommand(configPath);
  const commands = postCreateCommands(projectConfig);
  const ok = commands.includes(hook);
  return { ok, detail: ok ? 'post-create installs consented Claude local settings before launch; local files are excluded from Git'
    : 'AO postCreate must install Tally Claude local settings before the worker starts; run tally init for a new installation or apply the listed project fix',
    fix: setupPostCreateFixCommand(config.repo.aoProject!, projectConfig, hook) };
}

function postCreateCommands(projectConfig: unknown): string[] {
  if (!isRecord(projectConfig)) return [];
  const value = projectConfig.postCreate;
  if (Array.isArray(value)) return value.filter((item): item is string => typeof item === 'string');
  return [];
}

function withPostCreateCommand(config: unknown, command: string): Record<string, unknown> {
  const base = isRecord(config) ? { ...config } : {};
  const commands = postCreateCommands(base);
  base.postCreate = commands.includes(command) ? commands : [...commands, command];
  return base;
}

export function setupPostCreateFixCommand(projectId: string, projectConfig: unknown, setupCommand: string): string {
  return `ao project set-config ${projectId} --config-json ${quoteJsonForShell(withPostCreateCommand(projectConfig, setupCommand))}`;
}

export interface SetupPostCreateCheck {
  ok: boolean;
  detail: string;
  fix: string;
}

export function checkSetupPostCreate(projectId: string, projectConfig: unknown, setupCommand: string | undefined): SetupPostCreateCheck | null {
  if (!setupCommand) return null;
  const fix = setupPostCreateFixCommand(projectId, projectConfig, setupCommand);
  if (postCreateCommands(projectConfig).includes(setupCommand)) {
    return { ok: true, detail: `post-create runs setup command: ${setupCommand}`, fix };
  }
  return {
    ok: false,
    detail: `test.setupCommand is "${setupCommand}", but AO project postCreate does not run it before the worker starts`,
    fix,
  };
}

function sessionModeProblems(config: TallyConfig): string[] {
  return config.tiers.flatMap((tier, index) => {
    if (tier.sessionMode === 'tui') return [];
    const path = `tiers[${index}].sessionMode`;
    if (tier.sessionMode === 'chat') {
      return [`${path} is "chat"; real Tally workers need sessionMode: tui so unattended shell work does not route through chat approval prompts`];
    }
    return [`${path} is required for real runs; set sessionMode: tui after proving the harness can run unattended`];
  });
}

function parseAoProject(stdout: string): AoProjectResponse {
  return JSON.parse(stdout) as AoProjectResponse;
}

export async function validateRealRunConfig(config: TallyConfig, configPath: string, runner: PreflightRunner = defaultRunner): Promise<void> {
  if (runner === defaultRunner) runner = (file, args) => runCommand(file, args, { aoBin: config.repo.aoBin ? configRelative(configPath, config.repo.aoBin) : undefined });
  const problems: string[] = [];
  if (config.runner === 'direct') {
    const resolvedRepo = repoPath(config, configPath);
    if (!existsSync(resolvedRepo)) problems.push(`repo.path does not exist: ${resolvedRepo}`);
    const resolvedBacklog = backlogPath(config, configPath);
    if (resolvedBacklog && !existsSync(resolvedBacklog)) problems.push(`backlog.file does not exist: ${resolvedBacklog}`);
    if (config.repo.workerPublishesPr) problems.push('runner: direct requires repo.workerPublishesPr: false; Tally publishes the verified branch');
    if (problems.length) throw new ConfigError(configPath, problems);
    if (config.tiers.some(tier => tier.harness === 'claude-code')) requireClaudeConsent(config.claudeCode?.allow, config.test);
    for (const harness of new Set(config.tiers.map(tier => tier.harness))) await checkDirectHarness(harness, runner);
    return;
  }
  if (!config.repo.aoProject) problems.push('repo.aoProject is required for real runs so AO knows where to spawn workers');
  const resolvedRepo = repoPath(config, configPath);
  if (!existsSync(resolvedRepo)) problems.push(`repo.path does not exist: ${resolvedRepo}`);
  const resolvedBacklog = backlogPath(config, configPath);
  if (resolvedBacklog && !existsSync(resolvedBacklog)) problems.push(`backlog.file does not exist: ${resolvedBacklog}`);
  problems.push(...sessionModeProblems(config));
  if (config.repo.aoProject) {
    let project: AoProjectResponse | null = null;
    try {
      project = parseAoProject((await runner('ao', ['project', 'get', config.repo.aoProject, '--json'])).stdout);
    } catch (error) {
      if (error instanceof CommandError) throw error;
      problems.push(
        `repo.aoProject "${config.repo.aoProject}" is not registered in AO; fix: ao project add --path ${resolvedRepo} --id ${config.repo.aoProject}`,
      );
    }
    if (project) {
      const permission = checkConfiguredWorkerMode(config, project.project?.config);
      if (!permission.ok) {
        problems.push(`${permission.detail}; fix: ${permission.fix}`);
      }
      const setup = checkClaudePostCreate(config, configPath, project.project?.config)
        ?? checkSetupPostCreate(config.repo.aoProject, project.project?.config, config.test.setupCommand);
      if (setup && !setup.ok) {
        problems.push(`${setup.detail}; fix: ${setup.fix}`);
      }
    }
  }
  if (problems.length > 0) throw new ConfigError(configPath, problems);
  if (config.tiers.some(tier => tier.harness === 'claude-code')) requireClaudeConsent(config.claudeCode?.allow, config.test);
}
import { execFile } from 'node:child_process';
import { accessSync, constants, statSync } from 'node:fs';
import { homedir } from 'node:os';
import { delimiter, join, resolve } from 'node:path';
import { promisify } from 'node:util';

const execFileAsync = promisify(execFile);

export class CommandError extends Error {
  constructor(message: string, readonly code?: string | number, readonly stdout = '', readonly stderr = '') { super(message); }
}

function safeGitDiagnostic(value: string): string {
  return value
    .replace(/\u001b\[[0-9;]*m/g, '')
    .replace(/\b(?:github_pat_|gh[pousr]_)[a-zA-Z0-9_]+\b/gi, '[redacted]')
    .replace(/\bBearer\s+[^\s,;]+/gi, 'Bearer [redacted]')
    .replace(/\b(?:authorization|token|password|secret|api[-_ ]?key)\s*[:=]\s*[^\r\n]*/gi, '[credential redacted]')
    .replace(/https?:\/\/[^\s/@]+:[^\s/@]+@/gi, 'https://[redacted]@')
    .replace(/[\u0000-\u001f\u007f]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(-500);
}

export interface AoBinaryOptions {
  aoBin?: string;
  cwd?: string;
  env?: NodeJS.ProcessEnv;
  platform?: string;
  home?: string;
  bundleRoots?: string[];
}

export function resolveAoBinary(options: AoBinaryOptions = {}): string {
  const env = options.env ?? process.env;
  const cwd = options.cwd ?? process.cwd();
  const candidates = (env.PATH ?? '').split(delimiter).filter(Boolean).map((dir) => resolve(cwd, dir, 'ao'));
  for (const override of [env.TALLY_AO_BIN, options.aoBin]) if (override) candidates.push(resolve(cwd, override));
  if ((options.platform ?? process.platform) === 'darwin') {
    const suffix = 'Agent Orchestrator.app/Contents/Resources/daemon/ao';
    candidates.push(...(options.bundleRoots ?? ['/Applications', join(options.home ?? homedir(), 'Applications')]).map((root) => join(root, suffix)));
  }
  for (const candidate of candidates) {
    try {
      accessSync(candidate, constants.X_OK);
      if (statSync(candidate).isFile()) return candidate;
    } catch { /* Try the next explicit location. */ }
  }
  throw new CommandError(`Agent Orchestrator (AO) is required; looked in PATH (${env.PATH || 'empty'}), TALLY_AO_BIN (${env.TALLY_AO_BIN || 'unset'}), repo.aoBin (${options.aoBin || 'unset'}) and ${candidates.filter((path) => path.includes('.app/')).join(', ') || 'no app-bundle locations on this platform'}; install AO or set TALLY_AO_BIN to its executable path.`, 'ENOENT');
}

/** Resolve Entire's standard user-local install location even when the shell PATH omits it. */
export function resolveEntireBinary(options: Pick<AoBinaryOptions, 'platform' | 'home'> = {}): string {
  const platform = options.platform ?? process.platform;
  const home = options.home ?? homedir();
  const local = join(home, '.local', 'bin', platform === 'win32' ? 'entire.exe' : 'entire');
  try {
    accessSync(local, platform === 'win32' ? constants.F_OK : constants.X_OK);
    if (statSync(local).isFile()) return local;
  } catch { /* Fall back to the user's PATH. */ }
  return 'entire';
}

export async function runCommand(file: string, args: string[], options: AoBinaryOptions & { timeout?: number; maxBuffer?: number } = {}): Promise<{ stdout: string; stderr: string }> {
  const executable = file === 'ao' ? resolveAoBinary(options) : file === 'entire' ? resolveEntireBinary(options) : file;
  try {
    return await execFileAsync(executable, args, { cwd: options.cwd, env: options.env, timeout: options.timeout, maxBuffer: options.maxBuffer, encoding: 'utf8' });
  } catch (error) {
    const failure = error as { code?: string | number; signal?: string; stdout?: unknown; stderr?: unknown };
    const code = failure.code;
    const label = code ?? failure.signal ?? 'unknown error';
    const stderr = typeof failure.stderr === 'string' ? failure.stderr : '';
    const diagnostic = file === 'git' ? safeGitDiagnostic(stderr) : '';
    const operation = file === 'git' && args.includes('push') ? ' push'
      : file === 'git' && args.includes('commit') ? ' commit' : '';
    throw new CommandError(code === 'ENOENT'
      ? `${file} is required but could not be started; install it or add its executable to PATH${options.cwd ? `, and check that ${options.cwd} exists` : ''}.`
      : `${file}${operation} command failed (${label})${diagnostic ? `: ${diagnostic}` : '; check the command in your terminal before retrying.'}`, code,
      typeof failure.stdout === 'string' ? failure.stdout : '', stderr);
  }
}
import { existsSync, mkdirSync, readFileSync, unlinkSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { CommandError } from '../adapters/command.js';
import { configHash, contentHash, type InstallRecord } from './install-record.js';
import type { InitCommandRunner } from './init.js';
import { withWorkerPermissionMode } from './preflight.js';
import { AO_HARNESS_PERMISSIONS } from './harness.js';

export interface InitTransaction {
  version: 1;
  repoRoot: string;
  configPath: string;
  configText: string;
  beforeProjectConfigHash: string;
  newProjectInitialized?: boolean;
  completed?: string[];
  record: InstallRecord;
}

export function pendingInitPath(configPath: string): string {
  return resolve(dirname(configPath), '.tally', 'init-pending.json');
}

export function readPendingInit(configPath: string): InitTransaction | null {
  const path = pendingInitPath(configPath);
  if (!existsSync(path)) return null;
  let value: InitTransaction;
  try { value = JSON.parse(readFileSync(path, 'utf8')) as InitTransaction; }
  catch { throw new CommandError(`Invalid init recovery record at ${path}; preserve it and inspect it before retrying.`); }
  if (!value || typeof value !== 'object' || value.version !== 1 || value.configPath !== configPath || value.record?.configPath !== configPath ||
      typeof value.configText !== 'string' || contentHash(value.configText) !== value.record.configHash ||
      typeof value.beforeProjectConfigHash !== 'string' || typeof value.repoRoot !== 'string' ||
      value.record.version !== 1 || (value.record.runner !== undefined && !['ao', 'direct'].includes(value.record.runner)) || typeof value.record.projectId !== 'string' || typeof value.record.projectCreated !== 'boolean' || typeof value.record.projectConfigHash !== 'string') {
    throw new CommandError(`Invalid init recovery record at ${path}; preserve it and inspect it before retrying.`);
  }
  if (value.record.workerPermissionMode !== undefined && !['auto', 'default'].includes(value.record.workerPermissionMode)) throw new CommandError('Invalid init recovery worker permission mode.');
  if (value.record.aoHarnessPermissions && (typeof value.record.aoHarnessPermissions !== 'object' || Array.isArray(value.record.aoHarnessPermissions)
    || !Object.keys(value.record.aoHarnessPermissions).length || Object.entries(value.record.aoHarnessPermissions).some(([harness, mode]) => AO_HARNESS_PERMISSIONS[harness as keyof typeof AO_HARNESS_PERMISSIONS] !== mode))) throw new CommandError('Invalid init recovery harness permission modes.');
  return value;
}

export async function applyInitTransaction(transaction: InitTransaction, command: InitCommandRunner, recordPath: string): Promise<void> {
  const { configPath, configText, record, repoRoot } = transaction;
  const pendingPath = pendingInitPath(configPath);
  // Never overwrite files changed by the user while recovering an interrupted init.
  if (existsSync(configPath) && contentHash(readFileSync(configPath, 'utf8')) !== record.configHash) {
    throw new CommandError(`Init recovery refused: ${configPath} differs from the pending configuration; preserve your edits before retrying.`);
  }
  if (existsSync(recordPath) && configHash(JSON.parse(readFileSync(recordPath, 'utf8'))) !== configHash(record)) {
    throw new CommandError(`Init recovery refused: ${recordPath} differs from the pending ownership record.`);
  }
  let stage = 'creating recovery record';
  const completed = transaction.completed ?? [];
  const save = () => writeFileSync(pendingPath, JSON.stringify({ ...transaction, completed }, null, 2), { mode: 0o600 });
  try {
    mkdirSync(dirname(pendingPath), { recursive: true });
    if (!existsSync(pendingPath)) writeFileSync(pendingPath, JSON.stringify(transaction, null, 2), { mode: 0o600, flag: 'wx' });
    if ((record.runner ?? 'ao') === 'ao') {
      stage = 'reading AO project';
      let current: Record<string, unknown> | null;
      try {
        const payload = JSON.parse((await command('ao', ['project', 'get', record.projectId, '--json'], { cwd: repoRoot })).stdout);
        const path = payload.project?.path;
        if (typeof path === 'string' && resolve(path) !== resolve(repoRoot)) throw new CommandError(`AO project ${record.projectId} belongs to another repository (${path}); choose another project id.`);
        current = payload.project?.config ?? {};
      } catch (error) {
        if (!(error instanceof Error) || !/missing project|not found|HTTP 404/i.test(error.message)) throw error;
        if (!record.projectCreated) throw new CommandError(`Existing AO project ${record.projectId} disappeared; refusing to recreate a project Tally did not own.`);
        stage = 'registering AO project';
        await command('ao', ['project', 'add', '--path', repoRoot, '--id', record.projectId], { cwd: repoRoot });
        completed.push(`registered AO project ${record.projectId}`);
        save();
        current = JSON.parse((await command('ao', ['project', 'get', record.projectId, '--json'], { cwd: repoRoot })).stdout).project?.config ?? {};
      }
      const hash = configHash(current);
      if (!record.projectCreated && hash !== transaction.beforeProjectConfigHash && hash !== record.projectConfigHash) {
        throw new CommandError('AO project settings changed since init was proposed; refusing to overwrite them.');
      }
      const next = record.workerAfterHash ? withWorkerPermissionMode(current, record.workerPermissionMode ?? 'auto') : { ...current };
      if (record.addedSetupCommand) {
        const commands = Array.isArray(next.postCreate) ? next.postCreate as string[] : [];
        next.postCreate = commands.includes(record.addedSetupCommand) ? commands : [...commands, record.addedSetupCommand];
      }
      if (record.projectCreated && !transaction.newProjectInitialized) {
        // New AO projects can contain daemon defaults unknown before registration.
        record.projectConfigHash = configHash(next);
        record.postCreateExisted = Array.isArray(current?.postCreate);
        record.postCreateAfterHash = configHash(next.postCreate ?? []);
        if (record.workerAfterHash) {
          record.workerExisted = Object.hasOwn(current ?? {}, 'worker');
          record.workerBefore = current?.worker ?? null;
          record.workerAfterHash = configHash(next.worker);
        }
        if (record.addedSetupCommand && Array.isArray(current?.postCreate) && current.postCreate.includes(record.addedSetupCommand)) record.addedSetupCommand = null;
        transaction.newProjectInitialized = true;
        save();
      }
      if (configHash(next) !== record.projectConfigHash) {
        throw new CommandError('AO project configuration differs from the pending init; no settings were overwritten.');
      }
      stage = 'updating AO project configuration';
      await command('ao', ['project', 'set-config', record.projectId, '--config-json', JSON.stringify(next), '--json'], { cwd: repoRoot });
      completed.push(`configured AO project ${record.projectId}`);
      save();
    }
    stage = 'writing ownership record';
    if (existsSync(recordPath)) {
      if (configHash(JSON.parse(readFileSync(recordPath, 'utf8'))) !== configHash(record)) throw new CommandError('Ownership record changed during init; refusing to overwrite it.');
    } else writeFileSync(recordPath, JSON.stringify(record, null, 2), { mode: 0o600, flag: 'wx' });
    completed.push(`wrote ${recordPath}`);
    save();
    stage = 'writing tally.yaml';
    if (existsSync(configPath)) {
      if (contentHash(readFileSync(configPath, 'utf8')) !== record.configHash) throw new CommandError('tally.yaml changed during init; refusing to overwrite it.');
    } else writeFileSync(configPath, configText, { flag: 'wx' });
    completed.push(`wrote ${configPath}`);
    save();
  } catch (error) {
    throw new CommandError(`Init stopped while ${stage}: ${error instanceof Error ? error.message : 'unknown error'}; completed: ${completed.join(', ') || 'no AO or config changes confirmed'}; ${configPath} ${existsSync(configPath) ? 'exists' : 'was not written'}, ${recordPath} ${existsSync(recordPath) ? 'exists' : 'was not written'}; if the failed AO call did not return, its outcome must be checked on resume; recovery record ${existsSync(pendingPath) ? pendingPath : 'was not written'}; rerun tally init --config ${JSON.stringify(configPath)} to resume safely after fixing the error.`);
  }
